<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Plus, RefreshCw, Search, ShieldCheck, UserRound, Users, X } from 'lucide-vue-next'
import EntityCombobox, { type EntityOption } from '../../../packages/ui/EntityCombobox.vue'
import { confirmDialog } from './appDialog'

type Group = { id:string; name:string; description:string; is_active:boolean; permissions:string[]; member_count:number }
type User = { id:string; display_name:string; email:string; phone:string|null; is_active:boolean; verification_required:boolean; email_verified_at:string|null; last_login_at:string|null; created_at:string; professional_id:string|null; professional_name:string|null; has_avatar:boolean; groups:Array<{id:string;name:string;is_active?:boolean;active?:boolean}>; permissions?:string[]; invitation_sent?:boolean }
type Catalog = { actor_id:string; actor_permissions:string[]; permissions:Array<{key:string;description:string;delegable:boolean}>; password_min_length:number }
type Audit = { id:string;action:string;result:string;created_at:string;actor_name:string|null;metadata:Record<string,unknown> }
type Tab = 'users'|'groups'|'audit'
const props = defineProps<{ profileOnly?:boolean }>()
const catalog = ref<Catalog|null>(null), profile = ref<User|null>(null)
const users = ref<User[]>([]), groups = ref<Group[]>([]), audits = ref<Audit[]>([])
const tab = ref<Tab>('users'), query = ref(''), permissionFilter = ref('')
const loading = ref(false), saving = ref(false), error = ref(''), notice = ref(''), total = ref(0), offset = ref(0)
const userEditor = ref(false), groupEditor = ref(false), editingId = ref(''), selected = ref<User|null>(null)
const userForm = ref({display_name:'',email:'',phone:'',is_active:true,professional_id:'',group_ids:[] as string[]})
const professionalText = ref(''), professionalOptions = ref<EntityOption[]>([])
const groupForm = ref({name:'',description:'',is_active:true,permissions:[] as string[]})
const profileForm = ref({display_name:'',phone:''}), passwordForm = ref({current_password:'',new_password:'',confirmation:''}), emailForm = ref({email:'',current_password:''})
const avatarUrl = ref('')
let generation = 0
let queryTimer: ReturnType<typeof setTimeout> | undefined
const controller = new AbortController()
const can = (key:string) => catalog.value?.actor_permissions.includes(key) || false
const availableGroups = computed(() => groups.value.filter(g => g.permissions.every(p => can(p))))
const permissions = computed(() => (catalog.value?.permissions || []).filter(p => `${p.key} ${p.description}`.toLocaleLowerCase('pt-BR').includes(permissionFilter.value.toLocaleLowerCase('pt-BR'))))
const date = (value:string|null) => value ? new Date(value).toLocaleString('pt-BR') : 'Ainda não registrado'
const status = (u:User) => !u.is_active ? 'Desativado' : u.verification_required && !u.email_verified_at ? 'Convite pendente' : 'Ativo'
const auditLabels:Record<string,string> = {'iam.user.created':'Usuário cadastrado','iam.user.updated':'Usuário atualizado','iam.group.created':'Grupo criado','iam.group.updated':'Grupo atualizado','iam.email.requested':'Confirmação solicitada','iam.email.confirmed':'E-mail confirmado','iam.password.changed':'Senha alterada','iam.profile.updated':'Perfil atualizado','iam.profile.avatar':'Foto alterada','iam.user.access_revoked':'Acessos revogados'}
async function api<T>(path:string, init:RequestInit={}):Promise<T> {
  const response = await fetch(`/api/v1/access${path}`, {...init, signal: init.signal || controller.signal, cache:'no-store', headers:{ Accept:'application/json', ...(init.body && typeof init.body==='string'?{'Content-Type':'application/json'}:{}), ...init.headers }})
  const body = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(body.error?.message || `Falha HTTP ${response.status}`)
  return body.data as T
}
async function action(run:()=>Promise<void>):Promise<void> {
  if (saving.value) return
  saving.value=true;error.value='';notice.value=''
  try { await run() } catch (problem) { error.value=problem instanceof Error ? problem.message : 'Não foi possível concluir.' }
  finally { saving.value=false }
}
async function loadPage():Promise<void> {
  const request=++generation; loading.value=true;error.value=''
  try {
    if (props.profileOnly) {
      const value = await api<User>('/profile'); if(request!==generation)return
      profile.value=value;profileForm.value={display_name:value.display_name,phone:value.phone||''};await loadAvatar()
    } else if(tab.value==='users') {
      const value=await api<{items:User[];total:number}>(`/users?q=${encodeURIComponent(query.value)}&offset=${offset.value}`)
      if(request===generation){users.value=value.items;total.value=value.total}
    } else if(tab.value==='groups') groups.value=await api<Group[]>('/groups')
    else {
      const value=await api<{items:Audit[];total:number}>(`/audit?offset=${offset.value}`)
      if(request===generation){audits.value=value.items;total.value=value.total}
    }
  } catch(problem){if(request===generation)error.value=problem instanceof Error?problem.message:'Falha de consulta.'}
  finally{if(request===generation)loading.value=false}
}
async function load():Promise<void> {
  try {
    catalog.value=await api<Catalog>('/catalog')
    if (!props.profileOnly && !can('users.read')) tab.value=can('groups.manage')?'groups':'audit'
    if (!props.profileOnly && (can('users.read')||can('groups.manage'))) groups.value=await api<Group[]>('/groups')
    await loadPage()
  } catch(problem){error.value=String(problem)}
}
function selectTab(next:Tab):void{tab.value=next;offset.value=0;userEditor.value=false;groupEditor.value=false;selected.value=null;void loadPage()}
function createUser():void{editingId.value='';userForm.value={display_name:'',email:'',phone:'',is_active:true,professional_id:'',group_ids:[]};professionalText.value='';professionalOptions.value=[];userEditor.value=true;selected.value=null}
async function editUser(item:User):Promise<void>{await action(async()=>{const user=await api<User>(`/users/${item.id}`);editingId.value=user.id;userForm.value={display_name:user.display_name,email:user.email,phone:user.phone||'',is_active:user.is_active,professional_id:user.professional_id||'',group_ids:user.groups.map(g=>g.id)};professionalText.value=user.professional_name||'';professionalOptions.value=user.professional_id?[{id:user.professional_id,label:user.professional_name||''}]:[];userEditor.value=true;selected.value=null})}
async function inspectUser(item:User):Promise<void>{await action(async()=>{selected.value=await api<User>(`/users/${item.id}`);userEditor.value=false})}
async function searchProfessionals(q:string,signal:AbortSignal):Promise<EntityOption[]>{const rows=await api<Array<{id:string;name:string;linked_user_id:string|null}>>(`/professionals?q=${encodeURIComponent(q)}`,{signal});return rows.map(p=>({id:p.id,label:p.name,detail:p.linked_user_id&&p.linked_user_id!==editingId.value?'Já vinculado a outra conta':undefined,disabled:Boolean(p.linked_user_id&&p.linked_user_id!==editingId.value)}))}
async function saveUser():Promise<void>{await action(async()=>{
  const form=userForm.value
  const body:Record<string,unknown>={display_name:form.display_name,phone:form.phone||null,professional_id:form.professional_id||null,group_ids:form.group_ids}
  if(editingId.value)body.is_active=form.is_active;else body.email=form.email
  const result=await api<User>(editingId.value?`/users/${editingId.value}`:'/users',{method:editingId.value?'PUT':'POST',body:JSON.stringify(body)})
  notice.value=editingId.value?'Usuário atualizado. As permissões são revalidadas pelo servidor.':result.invitation_sent?'Conta criada e convite enviado por e-mail.':'Conta criada, mas o convite não foi enviado. Configure o SMTP e utilize Reenviar convite.'
  userEditor.value=false;await loadPage();window.dispatchEvent(new Event('scheduler-pro-profile-changed'))
})}
async function sendInvite(item:User):Promise<void>{await action(async()=>{const result=await api<{sent:boolean;message:string}>(`/users/${item.id}/invite`,{method:'POST'});notice.value=result.message})}
async function revokeUser(item:User):Promise<void>{if(!await confirmDialog({title:'Revogar acessos',message:`Encerrar as sessões e revogar os tokens de API de ${item.display_name}?`,confirmLabel:'Revogar',danger:true}))return;await action(async()=>{await api(`/users/${item.id}/revoke-access`,{method:'POST'});notice.value='Sessões encerradas e tokens revogados.'})}
function editGroup(item?:Group):void{editingId.value=item?.id||'';groupForm.value=item?{name:item.name,description:item.description||'',is_active:item.is_active,permissions:[...item.permissions]}:{name:'',description:'',is_active:true,permissions:[]};permissionFilter.value='';groupEditor.value=true}
async function saveGroup():Promise<void>{await action(async()=>{await api(editingId.value?`/groups/${editingId.value}`:'/groups',{method:editingId.value?'PUT':'POST',body:JSON.stringify(groupForm.value)});groupEditor.value=false;notice.value='Grupo salvo. Alterações de acesso valem na próxima requisição.';await load();window.dispatchEvent(new Event('scheduler-pro-profile-changed'))})}
async function saveProfile():Promise<void>{await action(async()=>{profile.value=await api<User>('/profile',{method:'PUT',body:JSON.stringify(profileForm.value)});notice.value='Perfil atualizado.';window.dispatchEvent(new Event('scheduler-pro-profile-changed'))})}
async function verifyEmail():Promise<void>{await action(async()=>{const value=await api<{sent:boolean}>('/profile/verify-email',{method:'POST'});notice.value=value.sent?'Confirmação enviada. Abra o link recebido.':'SMTP indisponível. Solicite a configuração ao administrador.'})}
async function changeEmail():Promise<void>{await action(async()=>{const value=await api<{sent:boolean}>('/profile/email',{method:'POST',body:JSON.stringify(emailForm.value)});emailForm.value.current_password='';notice.value=value.sent?'Enviamos a confirmação ao novo e-mail. Até confirmar, seu e-mail atual continua válido.':'Não foi possível enviar. O e-mail atual continua válido.'})}
async function changePassword():Promise<void>{if(passwordForm.value.new_password!==passwordForm.value.confirmation){error.value='A confirmação da senha não confere.';return}await action(async()=>{await api('/profile/password',{method:'POST',body:JSON.stringify({current_password:passwordForm.value.current_password,new_password:passwordForm.value.new_password})});passwordForm.value={current_password:'',new_password:'',confirmation:''};localStorage.removeItem('scheduler_pro_access_token');localStorage.removeItem('scheduler_pro_refresh_token');window.location.assign('/login')})}
async function loadAvatar():Promise<void>{if(avatarUrl.value){URL.revokeObjectURL(avatarUrl.value);avatarUrl.value=''}if(!profile.value?.has_avatar)return;const response=await fetch('/api/v1/access/profile/avatar',{cache:'no-store',signal:controller.signal});if(response.ok)avatarUrl.value=URL.createObjectURL(await response.blob())}
async function uploadPhoto(event:Event):Promise<void>{const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;if(file.size>2*1024*1024){error.value='A foto deve ter até 2 MB.';input.value='';return}await action(async()=>{await api('/profile/avatar',{method:'PUT',body:file,headers:{'Content-Type':file.type}});if(profile.value)profile.value.has_avatar=true;await loadAvatar();notice.value='Foto validada e salva.'});input.value=''}
async function removePhoto():Promise<void>{await action(async()=>{await api('/profile/avatar',{method:'DELETE'});if(profile.value)profile.value.has_avatar=false;await loadAvatar();notice.value='Foto removida.'})}
watch(query,()=>{clearTimeout(queryTimer);queryTimer=setTimeout(()=>{offset.value=0;void loadPage()},220)})
onMounted(()=>{void load()})
onBeforeUnmount(()=>{generation++;controller.abort();clearTimeout(queryTimer);if(avatarUrl.value)URL.revokeObjectURL(avatarUrl.value);passwordForm.value={current_password:'',new_password:'',confirmation:''};emailForm.value.current_password=''})
</script>

<template>
  <section class="iam-view" :aria-busy="loading || saving">
    <header class="iam-header"><div><small>SCHEDULER PRO · EMPRESA</small><h1>{{ profileOnly?'Meu perfil':'Usuários e grupos' }}</h1><p>{{ profileOnly?'Seus dados, foto e segurança de acesso.':'Contas individuais e permissões, isoladas nesta empresa.' }}</p></div><button class="btn" type="button" :disabled="loading || saving" @click="load"><RefreshCw :size="16"/> Atualizar</button></header>
    <p v-if="error" class="iam-error" role="alert">{{error}}</p><p v-if="notice" class="iam-notice" role="status">{{notice}}</p>
    <template v-if="profileOnly && profile">
      <div class="iam-profile-grid">
        <article class="iam-card iam-photo"><h2>Foto de perfil</h2><img v-if="avatarUrl" :src="avatarUrl" alt="Sua foto de perfil"><div v-else class="iam-initial">{{profile.display_name.slice(0,1).toUpperCase()}}</div><label class="btn">Escolher foto<input class="iam-file" type="file" accept="image/jpeg,image/png,image/webp" :disabled="saving" @change="uploadPhoto"></label><button v-if="profile.has_avatar" class="btn" :disabled="saving" @click="removePhoto">Remover foto</button><p>JPEG, PNG ou WebP estático, até 2 MB. A imagem é validada e seus metadados são removidos.</p></article>
        <form class="iam-card" @submit.prevent="saveProfile"><h2>Dados pessoais</h2><label>Nome<input v-model="profileForm.display_name" required minlength="2" maxlength="160" autocomplete="name"></label><label>Telefone<input v-model="profileForm.phone" type="tel" maxlength="40" autocomplete="tel"></label><label>E-mail atual<input :value="profile.email" type="email" readonly></label><p>{{ profile.email_verified_at?'E-mail confirmado.':'Conta preexistente preservada; e-mail ainda não confirmado.' }}</p><button v-if="!profile.email_verified_at" type="button" class="btn" :disabled="saving" @click="verifyEmail">Confirmar meu e-mail</button><p>Profissional vinculado: <strong>{{profile.professional_name||'Nenhum (não obrigatório)'}}</strong></p><button class="btn primary" :disabled="saving">Salvar perfil</button></form>
        <form class="iam-card" @submit.prevent="changePassword"><h2>Alterar senha</h2><p>As sessões e os tokens de API serão revogados. Você precisará entrar novamente.</p><label>Senha atual<input v-model="passwordForm.current_password" type="password" required maxlength="512" autocomplete="current-password"></label><label>Nova senha<input v-model="passwordForm.new_password" type="password" required :minlength="catalog?.password_min_length||12" maxlength="512" autocomplete="new-password"></label><label>Confirmar nova senha<input v-model="passwordForm.confirmation" type="password" required maxlength="512" autocomplete="new-password"></label><button class="btn primary" :disabled="saving">Alterar senha com segurança</button></form>
        <form class="iam-card" @submit.prevent="changeEmail"><h2>Alterar e-mail de acesso</h2><p>A alteração só ocorre depois da confirmação no novo endereço.</p><label>Novo e-mail<input v-model="emailForm.email" type="email" required maxlength="180" autocomplete="email"></label><label>Senha atual<input v-model="emailForm.current_password" type="password" required maxlength="512" autocomplete="current-password"></label><button class="btn" :disabled="saving">Enviar confirmação</button><h3>Seus acessos</h3><div class="iam-tags"><span v-for="group in profile.groups" :key="group.id">{{group.name}}</span></div><details><summary>Permissões efetivas</summary><div class="iam-tags"><code v-for="permission in profile.permissions" :key="permission">{{permission}}</code></div></details></form>
      </div>
    </template>
    <template v-else-if="!profileOnly && catalog">
      <nav class="iam-tabs" aria-label="Gestão de acessos"><button v-if="can('users.read')" :class="{active:tab==='users'}" @click="selectTab('users')"><UserRound :size="16"/> Usuários</button><button v-if="can('groups.manage')||can('users.read')" :class="{active:tab==='groups'}" @click="selectTab('groups')"><Users :size="16"/> Grupos e permissões</button><button v-if="can('users.audit')" :class="{active:tab==='audit'}" @click="selectTab('audit')"><ShieldCheck :size="16"/> Histórico</button></nav>
      <template v-if="tab==='users'">
        <div class="iam-toolbar"><label class="iam-search"><Search :size="17"/><input v-model="query" type="search" placeholder="Buscar por nome ou e-mail" aria-label="Buscar usuários"></label><span>{{total}} conta(s)</span><button v-if="can('users.manage')" class="btn primary" @click="createUser"><Plus :size="16"/> Novo usuário</button></div>
        <form v-if="userEditor" class="iam-card" @submit.prevent="saveUser"><div class="iam-card-title"><h2>{{editingId?'Editar usuário':'Nova conta individual'}}</h2><button class="btn" type="button" aria-label="Fechar formulário" @click="userEditor=false"><X :size="17"/></button></div><p v-if="!editingId">A pessoa receberá um convite para confirmar seu e-mail e definir a própria senha. Nenhuma senha será enviada por mensagem.</p><div class="iam-fields"><label>Nome<input v-model="userForm.display_name" required minlength="2" maxlength="160" autocomplete="name"></label><label>E-mail de acesso<input v-model="userForm.email" type="email" required maxlength="180" :readonly="Boolean(editingId)" autocomplete="off"><small v-if="editingId">A alteração de e-mail é confirmada pelo próprio usuário em Meu perfil.</small></label><label>Telefone<input v-model="userForm.phone" type="tel" maxlength="40"></label><label>Profissional (opcional)<EntityCombobox v-model="userForm.professional_id" v-model:text="professionalText" :options="professionalOptions" :search="searchProfessionals" label="Profissional vinculado" placeholder="Buscar profissional ou deixar vazio"/></label></div><p>O vínculo não cria conta para o profissional nem concede permissões. Deixe vazio para um usuário apenas administrativo.</p><fieldset><legend>Grupos de acesso</legend><div class="iam-choices"><label v-for="group in availableGroups" :key="group.id"><input v-model="userForm.group_ids" type="checkbox" :value="group.id">{{group.name}} <small v-if="!group.is_active">(desativado)</small></label><p v-if="!availableGroups.length">Nenhum grupo delegável disponível.</p></div></fieldset><label v-if="editingId" class="iam-check"><input v-model="userForm.is_active" type="checkbox">Conta ativa</label><div class="iam-actions"><button type="button" class="btn" @click="userEditor=false">Cancelar</button><button class="btn primary" :disabled="saving">{{saving?'Salvando…':editingId?'Salvar usuário':'Criar conta e enviar convite'}}</button></div></form>
        <article v-if="selected" class="iam-card"><div class="iam-card-title"><h2>{{selected.display_name}}</h2><button class="btn" aria-label="Fechar detalhes" @click="selected=null"><X :size="17"/></button></div><p>{{selected.email}} · {{status(selected)}}</p><p>Último acesso: {{date(selected.last_login_at)}}. Cadastro: {{date(selected.created_at)}}.</p><p>Profissional: {{selected.professional_name||'Sem vínculo'}}</p><div class="iam-tags"><span v-for="group in selected.groups" :key="group.id">{{group.name}}</span></div><details open><summary>Permissões efetivas</summary><div class="iam-tags"><code v-for="permission in selected.permissions" :key="permission">{{permission}}</code></div></details></article>
        <div class="iam-user-list"><article v-for="item in users" :key="item.id" class="iam-user"><div class="iam-user-icon">{{item.display_name.slice(0,1).toUpperCase()}}</div><div class="iam-user-info"><strong>{{item.display_name}}</strong><span>{{item.email}}</span><small>Último acesso: {{date(item.last_login_at)}}</small><div class="iam-tags"><span v-for="group in item.groups" :key="group.id">{{group.name}}</span></div></div><span class="iam-status" :class="{inactive:!item.is_active}">{{status(item)}}</span><div class="iam-actions"><button class="btn small" @click="inspectUser(item)">Detalhes</button><template v-if="can('users.manage')&&item.id!==catalog.actor_id"><button class="btn small" @click="editUser(item)">Editar</button><button class="btn small" :disabled="saving||!item.is_active" @click="sendInvite(item)">{{item.verification_required&&!item.email_verified_at?'Reenviar convite':'Confirmar e-mail'}}</button><button class="btn small" :disabled="saving" @click="revokeUser(item)">Revogar acessos</button></template></div></article><p v-if="!users.length&&!loading" class="iam-card">Nenhum usuário encontrado.</p></div>
      </template>
      <template v-else-if="tab==='groups'">
        <div class="iam-toolbar"><p>Grupos reutilizam os perfis de acesso existentes.</p><button v-if="can('groups.manage')" class="btn primary" @click="editGroup()"><Plus :size="16"/> Novo grupo</button></div>
        <form v-if="groupEditor" class="iam-card" @submit.prevent="saveGroup"><h2>{{editingId?'Editar grupo':'Novo grupo'}}</h2><div class="iam-fields"><label>Nome<input v-model="groupForm.name" required minlength="2" maxlength="120"></label><label>Descrição<input v-model="groupForm.description" maxlength="1000"></label></div><label class="iam-check"><input v-model="groupForm.is_active" type="checkbox">Grupo ativo</label><label>Localizar permissão<input v-model="permissionFilter" type="search" placeholder="Agenda, clientes, usuários…"></label><div class="iam-choices"><label v-for="permission in permissions" :key="permission.key"><input v-model="groupForm.permissions" type="checkbox" :value="permission.key" :disabled="!permission.delegable"><span>{{permission.description||permission.key}}<small>{{permission.key}}{{permission.delegable?'':' · não delegável'}}</small></span></label></div><p>O servidor rejeita qualquer tentativa de conceder privilégios superiores e protege o último administrador.</p><div class="iam-actions"><button type="button" class="btn" @click="groupEditor=false">Cancelar</button><button class="btn primary" :disabled="saving">Salvar grupo</button></div></form>
        <div class="iam-group-grid"><article v-for="group in groups" :key="group.id" class="iam-card"><h2>{{group.name}}</h2><p>{{group.description}}</p><span>{{group.member_count}} usuário(s) · {{group.is_active?'Ativo':'Desativado'}}</span><details><summary>{{group.permissions.length}} permissões</summary><div class="iam-tags"><code v-for="permission in group.permissions" :key="permission">{{permission}}</code></div></details><button v-if="can('groups.manage')" class="btn" :disabled="!group.permissions.every(p=>can(p))" @click="editGroup(group)">Editar grupo</button></article></div>
      </template>
      <template v-else><div class="iam-audit"><article v-for="item in audits" :key="item.id" class="iam-card"><div class="iam-card-title"><strong>{{auditLabels[item.action]||item.action}}</strong><time>{{date(item.created_at)}}</time></div><p>{{item.actor_name||'Confirmação por e-mail'}} · {{item.result}}</p><details><summary>Detalhes da ação</summary><pre>{{JSON.stringify(item.metadata,null,2)}}</pre></details></article><p v-if="!audits.length&&!loading">Nenhuma ação registrada.</p></div></template>
      <div v-if="tab!=='groups'" class="iam-pagination"><button class="btn" :disabled="offset===0||loading" @click="offset=Math.max(0,offset-25);loadPage()">Anterior</button><span>Página {{offset/25+1}}</span><button class="btn" :disabled="offset+25>=total||loading" @click="offset+=25;loadPage()">Próxima</button></div>
    </template>
    <p v-if="loading" role="status">Atualizando dados…</p>
  </section>
</template>

<style scoped>
